SELECT  FROM transport_command
WHERE task_id = #{taskId}
ORDER BY created_at, command_id

SELECT FROM transport_command WHERE task_id IN
#{taskId}
ORDER BY task_id, created_at DESC, command_id DESC

mapper.update:
UPDATE transport_command
SET status = 'SUCCEEDED', completed_at = #{completedAt}
WHERE command_id = #{commandId} AND status IN ('CREATED', 'PUBLISHED')

UPDATE transport_command
SET status = 'FAILED', failure_reason = #{failureReason}, completed_at = #{completedAt}
WHERE command_id = #{commandId} AND status IN ('CREATED', 'PUBLISHED')

UPDATE transport_command
SET status = 'PUBLISH_FAILED', failure_reason = #{failureReason}
WHERE command_id = #{commandId} AND status = 'CREATED'

UPDATE transport_command
SET status = 'TIMEOUT', failure_reason = #{failureReason}, completed_at = #{completedAt}
WHERE command_id = #{commandId} AND status IN ('CREATED', 'PUBLISHED')

UPDATE transport_command
SET status = #{next},
    failure_reason = #{failureReason},
    completed_at = #{completedAt}
WHERE command_id = #{commandId} AND status = #{expected}
